def tim_cap_co_tong(nums, target):
    """Trả về chỉ số của hai phần tử cộng lại bằng target."""
    ket_qua = []
    for i in range(len(nums)):
        for j in range(len(nums)):
            if i == j:
                continue
            if nums[i] + nums[j] == target:
                ket_qua.append((i, j))
    return ket_qua


def loc_trung_lap(cap):
    da_thay = set()
    sach = []
    for a, b in cap:
        khoa = tuple(sorted((a, b)))
        if khoa not in da_thay:
            da_thay.add(khoa)
            sach.append((a, b))
    return sach
